def transform(grid):
    h, w = len(grid), len(grid[0])
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    r0 = min(r for r, c in zeros)
    r1 = max(r for r, c in zeros)
    c0 = min(c for r, c in zeros)
    c1 = max(c for r, c in zeros)

    def inside(r, c):
        return r0 <= r <= r1 and c0 <= c <= c1

    counts = {}
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or inside(r, c) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = rr + dr, cc + dc
                        if (0 <= nr < h and 0 <= nc < w and
                                not inside(nr, nc) and
                                grid[nr][nc] == color and
                                (nr, nc) not in seen):
                            seen.add((nr, nc))
                            stack.append((nr, nc))
            counts[color] = counts.get(color, 0) + 1

    out = [[0] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            color = grid[r][c]
            if color != 0:
                n = max(1, counts.get(color, 0))
                for k in range(n):
                    col = c - c0 + 2 * k
                    if col < len(out[0]):
                        out[r - r0][col] = color
    return out
